testWidgets('seek preview during drag', (tester) async {
  final isLinux = defaultTargetPlatform == TargetPlatform.linux;
  final previewTargets = <int>[];
  final previewDurations = <int>[];
  var dragEnded = 0;

  final b = build(
    positionMs: 10000,
    durationMs: 60000,
    onSeekDragEnded: () => dragEnded++, 
    onSeekPreview: (targetMs, durationMs) {
      previewTargets.add(targetMs);
      previewDurations.add(durationMs);
    },
  );
  await tester.pumpWidget(host(b.widget));

  final gesture = await tester.startGesture(
      tester.getCenter(find.byType(HeroFeedbackSurface)));
  await gesture.moveBy(const Offset(120, 0));
  await tester.pump();

  expect(previewTargets, isNotEmpty,
      reason: 'onSeekPreview must fire while dragging');
  expect(previewDurations, everyElement(equals(60000)));

  if (isLinux) {
    // Linux suppresses the centre HUD so the seek preview can live in the
    // bottom crumb line instead.
    expect(find.byKey(HeroFeedbackSurface.seekHudKey), findsNothing);
  } else {
    expect(find.byKey(HeroFeedbackSurface.seekHudKey), findsOneWidget);
    // Readout is "m:ss / m:ss".
    expect(find.textContaining(' / 1:00'), findsOneWidget);
  }

  await gesture.up();
  await tester.pump();

  expect(dragEnded, 1);
  // HUD is gone once the drag ends (or suppressed entirely on Linux).
  expect(find.byKey(HeroFeedbackSurface.seekHudKey), findsNothing);
});

